answers.solution:
**Root cause:** Next.js `output: 'standalone'` file tracing follows *static imports only*; the federation runtime (`src/lib/federation` + `src/lib/db` + `src/lib/dataDir.js`) is reached only via dynamic `import()` from `custom-server.js`, so it's absent from `.next/standalone`. `FEDERATION_MODE=edge` booted anyway and silently fell through to local handlers.

**Part 1 — Dockerfile: explicitly COPY the dynamic-import runtime set** (the standalone trace can never see it):

```dockerfile
COPY --from=builder /app/.next/standalone ./
COPY --from=builder /app/.next/static ./.next/static
COPY --from=builder /app/public ./public
# Dynamic-import runtime set — NOT in the standalone trace:
COPY --from=builder /app/src/lib/federation ./src/lib/federation
COPY --from=builder /app/src/lib/db           ./src/lib/db
COPY --from=builder /app/src/lib/dataDir.js   ./src/lib/dataDir.js
CMD ["node", "custom-server.js"]
```

**Part 2 — custom-server.js: pure boot guard + FATAL exit(1)** before any socket binds:

```js
const REQUIRED_RUNTIME_MODULES = {
  edge:    ['src/lib/federation/index.js', 'src/lib/db/index.js', 'src/lib/dataDir.js'],
  central: ['src/lib/federation/index.js', 'src/lib/db/index.js', 'src/lib/dataDir.js'],
};

// Pure helper: fs.existsSync probes only, no side effects, unit-testable.
function missingFederationRuntimeModules({ dir, mode }) {
  const required = REQUIRED_RUNTIME_MODULES[mode] || [];   // 'local' => [] (zero drift)
  return required.filter((rel) => !fs.existsSync(path.join(dir, rel)));
}

if (require.main === module) {
  let mode = resolveMode();                       // unknown mode => throw => exit(1)
  const missing = missingFederationRuntimeModules({ dir: __dirname, mode });
  if (missing.length > 0) {
    console.error(`[FATAL] FEDERATION_MODE=${mode} requires absent modules:`);
    for (const rel of missing) console.error(`  MISSING  ${rel}`);
    process.exit(1);                              // fail-closed, never inert
  }
  // ...loader: dynamic import .catch() also exits(1) — never serves local data
}
```

The runtime loader's `import()` `.catch` also exits(1) (a loader failure after a green guard is a real error, not a fallback signal), and bind failures (`server.on('error')`) FATAL too.
